import { taxCents } from "./tax";

export interface Invoice {
  id: string;
  subtotalCents: number;
  taxRatePercent: number;
}

export function totalCents(invoice: Invoice): number {
  return invoice.subtotalCents + taxCents(invoice.subtotalCents, invoice.taxRatePercent);
}

